//! 🛬️ Source-owned decoder admission and loan return.
use super::{OriginalCallerSourceLoan as SourceLoan,OriginalTurnFailure as Failure,OriginalNativeReceivingOutcome as Outcome,StepContext};
use semio_framework_job_return_budget as stock;
use crate::original_job_continuation::source::OriginalReturnSourceInput as Input;
use semio_framework_job_receiving::{OriginalDecodeState as State,OriginalReceivingOperation as Operation};
use semio_framework_value_retained_clone::{ValueError,RetirementDemand,RetainedCloneGrant as G,RetainedCloneProgress as P};
use semio_framework_value_native_owned::native_decoding::{NativeDecodeProgress,NativeDecodeWorkRecipient,NativeDecodeCallFailure,NativeRetirementDecodeControl as Recovery};
type ScopeLoan=stock::OriginalReturnScopeLoan<Input>;
use stock::OriginalReturnEscrowAmounts as Amounts;
pub struct OriginalJobDecodeOwner{source:std::mem::ManuallyDrop<Option<SourceLoan>>,pub(crate) scope:Option<ScopeLoan>,state:State}
impl OriginalJobDecodeOwner{
 pub fn empty()->Self{Self{source:std::mem::ManuallyDrop::new(None),scope:None,state:State::empty()}}
 pub fn work_issuer_birth_copy_bytes()->usize{State::work_issuer_birth_copy_bytes()}
 pub fn source_loan_admitted(&self)->bool{self.source.is_some()}
 pub fn admit_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,Failure>{if self.state.is_closing(){return Err(ValueError::invariant("decoder closing").into())}if self.source.is_none(){cx.original_source_parent()?.admit_loan(&mut self.source,cx)?;return Ok(false)}self.source.as_ref().unwrap().validate_context(cx)?;if self.state.work_issuer_admitted(){return Ok(true)}if cx.should_yield()||cx.is_cancelled(){return Ok(false)}let turn=self.state.admit_work_issuer(cx.retained_grant(),cx.fuel_remaining());let ready=turn.result?;if ready{let progress=P{copied_items:1,copied_bytes:Self::work_issuer_birth_copy_bytes(),..Default::default()};let receipt=cx.consume_retained(progress);cx.consume_fuel(turn.work);receipt?;}Ok(ready)}
 pub(crate) fn validate_source(&self,cx:&StepContext<'_>,retirement:bool)->Result<(),Failure>{let source=self.source.as_ref().ok_or_else(||ValueError::invariant("decoder Source absent"))?;if retirement{source.validate_retirement_context(cx)}else{source.validate_context(cx)}?;if !self.state.work_issuer_admitted(){return Err(ValueError::invariant("work issuer absent").into())}Ok(())}
 pub(crate) fn retire<T,E:From<ValueError>>(&mut self,grant:G,callback:&mut dyn FnMut(NativeDecodeProgress)->bool,deadline:&mut dyn FnMut()->bool,work:&mut dyn NativeDecodeWorkRecipient,observed:&mut u64,operation:impl FnOnce(&mut Recovery<'_, '_>)->Result<T,E>)->Result<T,NativeDecodeCallFailure<T,E>>{self.state.retire(grant,callback,deadline,work,observed,operation)}
 pub fn retirement_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.state.terminal_is_empty(){return self.state.retirement_demands(body)}Ok(RetirementDemand{copy_bytes:if self.source.is_some(){std::mem::size_of::<Option<SourceLoan>>()}else{0},depth:usize::from(self.source.is_some()),..Default::default()})}
 /// 🧹️ Returns decoder state before its Source alias.
 pub fn close_on_source(&mut self,cx:&mut StepContext<'_>)->Result<bool,Failure>{if self.terminal_is_empty(){return Ok(true)}if self.scope.is_some(){return Err(ValueError::invariant("decoder retains receiving stock").into())}if let Some(source)=self.source.as_ref(){source.validate_retirement_context(cx)?;}if !self.state.terminal_is_empty(){let demand=self.state.retirement_demands(cx.retained_grant().maximum_copy_bytes)?;super::close_original_retained_step(cx,demand,|grant|self.state.close_step(grant))?;return Ok(false)}let Some(loan)=self.source.as_mut()else{return Ok(true)};let parent=cx.original_source_parent()?;if !matches!(loan.close_step(parent,cx)?,super::InteractiveJobCloseStep::Complete{..}){return Ok(false)}let bytes=std::mem::size_of::<Option<SourceLoan>>();let grant=cx.retained_grant();if cx.retirement_should_yield()||grant.maximum_items==0||grant.maximum_copy_bytes<bytes||grant.maximum_depth==0{return Ok(false)}cx.consume_retained(P{copied_items:1,copied_bytes:bytes,..Default::default()})?;cx.consume_fuel(1);self.source.take();Ok(true)}
 pub fn terminal_is_empty(&self)->bool{self.state.terminal_is_empty()&&self.source.is_none()&&self.scope.is_none()}
}
impl std::ops::Deref for OriginalJobDecodeOwner{type Target=State;fn deref(&self)->&Self::Target{&self.state}}
impl Drop for OriginalJobDecodeOwner{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"decoder needs Source retirement")}}

impl StepContext<'_>{
 /// 📏️ False setup can post real origin/table progress; this query quotes its next actual owner phase.
 pub fn native_receiving_setup_demand(&self)->Result<Option<(usize,RetirementDemand,u64)>,Failure>{let b=self.return_budget.as_ref().ok_or_else(||ValueError::invariant("Source budget absent"))?.get();Ok(stock::original_return_scope_setup_demand(b.is_bound(),b.table.is_some()))}

 pub fn native_receiving_requires_recovery(&self)->bool{self.original_decoder.as_deref().is_some_and(|owner|owner.has_pending_receiving())}
 /// 🫴️ Stores the full recovery outcome before Source posting.
 pub fn with_native_retirement_receiving(&mut self,out:&mut Option<Outcome>,operation:impl FnOnce(&mut Recovery<'_, '_ >,G)->Result<(),ValueError>)->Result<bool,Failure>{let mut operation=Some(operation);self.original_receiving_outcome(out,Operation::Recover(&mut |native,grant|operation.take().unwrap()(native,grant)))}
 /// 🧳️ Retains typed output through original Source return.
 pub fn with_native_retirement_receiving_value<T>(&mut self,out:&mut Option<Outcome<T>>,operation:impl FnOnce(&mut Recovery<'_, '_>,G)->Result<T,ValueError>)->Result<bool,Failure>{let mut operation=Some(operation);self.original_receiving_outcome(out,Operation::RecoverValue(&mut|native,grant|operation.take().unwrap()(native,grant)))}
 fn native_scope_quantum(&self)->G{stock::original_return_scope_quantum(self.retained_progress(),self.reserved_return_progress,self.retained,self.retained_policy)}
 fn observe_native_scope(&mut self)->Result<(),ValueError>{let grant=self.native_scope_quantum();let Self{original_decoder,return_budget,retained_progress,work_units_spent,fuel_remaining,reserved_return_progress,reserved_return_work,original_physical_recipient,original_work_recipient,reserved_observer,..}=self;let Some(owner)=original_decoder.as_deref_mut()else{return Ok(())};let Some(loan)=owner.scope.as_mut()else{return Ok(())};let b=return_budget.as_mut().ok_or_else(||ValueError::invariant("Source scope budget absent"))?.get_mut();let counters=stock::OriginalReturnScopeCounters{physical:&mut**retained_progress,work:work_units_spent,fuel:fuel_remaining,reserved:reserved_return_progress,reserved_work:reserved_return_work,aggregate_physical:original_physical_recipient.as_ref().map(|(p,start)|(&**p,*start)),aggregate_work:original_work_recipient.as_deref(),reserved_observer:reserved_observer.as_mut().map(|(p,w)|(&mut**p,&mut**w)),grant};if b.observe_scope(loan,counters)?{owner.scope.take();}Ok(())}
 pub(super) fn original_receiving_outcome<T>(&mut self,out:&mut Option<Outcome<T>>,operation:Operation<'_,T>)->Result<bool,Failure>{
  let retirement=operation.is_retirement();let typed=operation.is_typed();let placement=if typed{Outcome::<T>::typed_placement()?}else{Outcome::<T>::placement()};let placement_work=if typed{Outcome::<T>::typed_placement_work()?}else{0};if out.is_some(){return Err(ValueError::invariant("receiving destination occupied").into())}self.original_decoder.as_deref().ok_or_else(||ValueError::invariant("receiving decoder absent"))?.validate_source(self,retirement)?;
  if self.return_budget.as_ref().is_none_or(|b|b.get().table.is_none()){self.admit_original_return_table()?;return Ok(false)}
  self.observe_native_scope()?;if !retirement&&self.original_decoder.as_deref().unwrap().state.has_pending_receiving(){return Err(ValueError::invariant("pending decoder requires original recovery").into())}
  if (!retirement&&(self.is_cancelled()||self.deadline_exceeded()))||(retirement&&!self.original_retirement&&self.deadline_exceeded()){return Ok(false)}
  let local=self.return_budget.as_ref().unwrap().get().delivery==stock::OriginalReturnDelivery::LocalWitness;let owner=self.original_decoder.as_deref().unwrap();let existing=match owner.scope.as_ref(){Some(loan)=>self.return_budget.as_ref().unwrap().get().scope_remaining(loan)?,None=>Amounts::default()};let Some(plan)=stock::OriginalReturnScopePlan::quote::<Input>(self.retained_grant(),self.native_scope_quantum(),self.fuel_remaining(),self.fuel_remaining,existing,owner.scope.is_some(),owner.state.pending_work(),owner.state.has_pending_receiving(),retirement,local,placement,placement_work)?else{return Ok(false)};
  let epoch=self.original_source_epoch().unwrap_or(0);let admitted={let Self{original_decoder,return_budget,..}=self;return_budget.as_mut().unwrap().get_mut().admit_scope(&mut original_decoder.as_deref_mut().unwrap().scope,plan.wanted,epoch)?};let Some((progress,work))=admitted else{return Ok(false)};let posted=self.consume_retained(progress);self.consume_fuel(work);posted?;if !plan.ready{return Ok(false)}
  let before=self.retained_progress();let result={let Self{original_decoder,return_budget,retained_progress,deadline_us,now_us,original_retirement,cancel,..}=self;let mut ready=||if retirement{*original_retirement||now_us().is_some_and(|now|now<*deadline_us)}else{!cancel.is_cancelled_now()&&now_us().is_some_and(|now|now<*deadline_us)};let owner=original_decoder.as_deref_mut().unwrap();owner.state.run_scoped_on_caller(return_budget.as_mut().unwrap().get_mut(),owner.scope.as_ref().unwrap(),out,&plan,before,&mut**retained_progress,&mut ready,operation)};if out.is_none(){result?;return Ok(false)}out.as_mut().unwrap().source_refusal=match result{Err(error)=>Some(error),Ok(())=>self.observe_native_scope().err()};Ok(true)
 }
}
